// Общие шаги фильтров /search и /mapview (#b4b8c9: диапазон цены с 0, мин и макс; убраны מחזור שנתי / רווח שנתי / שנות פעילות).
// Прод, только чтение: не-GET запросы обрываются, cookie — «только необходимые», service worker заблокирован (test.use в spec).
// Ожидаемые выдачи не хардкодятся: каталог берётся из ответа GET rest/v1/business, который делает сам сайт при загрузке.
import { expect, BrowserContext, Locator, Page } from '@playwright/test';

export const LOAD = { timeout: 30_000 };
/** Верхняя граница ползунка: ручка макс у края = «без ограничения». */
export const PRICE_EDGE = 10_000_000;
export const REMOVED_FILTERS = ['מחזור שנתי', 'רווח שנתי', 'שנות פעילות'] as const;
export const LEGACY_PARAMS =
  'minRevenue=5000000&maxRevenue=6000000&minProfit=2000000&maxProfit=3000000&minYears=30&maxYears=40';
/** Блок рекомендаций под выдачей (12 карточек) — не фильтруется, в сверку не входит. */
const RELATED_TITLE = 'עסקים נוספים שעשויים לעניין אותך';
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

export type Biz = { id: string; price: number | string | null; category?: string | null; city?: string | null };
export type EnterMode = 'type' | 'fill';

export const fmt = (n: number) => `₪${n.toLocaleString('en-US')}`;
export const priceOf = (b: Biz) => Number(b.price ?? 0);

/** Вызывать до первого перехода. */
export async function prepareReadOnly(context: BrowserContext) {
  await context.route('**/*', (route) =>
    SAFE_METHODS.includes(route.request().method()) ? route.fallback() : route.abort('blockedbyclient'),
  );
  await context.addInitScript(() => {
    try {
      if (!localStorage.getItem('cookie-consent-v2')) {
        localStorage.setItem(
          'cookie-consent-v2',
          JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
        );
      }
    } catch {}
  });
}

/**
 * Слушает ответы GET rest/v1/business (каталог, который загружает сайт). Вызывать до page.goto.
 * Возвращает функцию, которая дожидается каталога и отдаёт самый полный ответ.
 */
export function captureCatalog(page: Page): () => Promise<Biz[]> {
  const lists: Biz[][] = [];
  page.on('response', async (r) => {
    if (r.request().method() !== 'GET' || !/\/rest\/v1\/business\?/.test(r.url()) || !r.ok()) return;
    try {
      const j = await r.json();
      if (Array.isArray(j) && j.length && j[0] && 'id' in j[0] && 'price' in j[0]) lists.push(j as Biz[]);
    } catch {}
  });
  return async () => {
    await expect
      .poll(() => lists.length, { message: 'сайт загрузил каталог объявлений (GET rest/v1/business)', ...LOAD })
      .toBeGreaterThan(0);
    return lists.reduce((a, b) => (b.length > a.length ? b : a));
  };
}

/** id объявлений каталога с ценой в [min, max]; max = null — без верхней границы. */
export function idsInRange(catalog: Biz[], min: number, max: number | null, among?: string[]): string[] {
  const pool = among ? catalog.filter((b) => among.includes(b.id)) : catalog;
  return pool
    .filter((b) => priceOf(b) >= min && (max === null || priceOf(b) <= max))
    .map((b) => b.id)
    .sort();
}

/** Число из «נמצאו N עסקים»; «לא נמצאו…» = 0. */
export async function foundCount(page: Page): Promise<number> {
  const el = page.getByText(/נמצאו\s+[\d,]+\s+עסקים|לא נמצאו/).filter({ visible: true }).first();
  await expect(el).toBeVisible(LOAD);
  const t = await el.innerText();
  const m = t.match(/נמצאו\s+([\d,]+)/);
  return m && !/לא נמצאו/.test(t) ? Number(m[1].replace(/,/g, '')) : 0;
}

/** id объявлений выдачи — ссылки businessdetail?id= ДО заголовка блока рекомендаций (он не фильтруется). */
export async function resultIds(page: Page): Promise<string[]> {
  const ids = await page.evaluate((title) => {
    const h = [...document.querySelectorAll('h1,h2,h3,h4')].find((x) => (x as HTMLElement).innerText.includes(title));
    return [...document.querySelectorAll<HTMLAnchorElement>('a[href*="businessdetail?id="]')]
      .filter((a) => !h || h.compareDocumentPosition(a) & Node.DOCUMENT_POSITION_PRECEDING)
      .map((a) => new URL(a.href).searchParams.get('id') || '');
  }, RELATED_TITLE);
  return [...new Set(ids.filter(Boolean))].sort();
}

/** Выдача = ожидаемый набор: сначала «נמצאו N», затем сами id. */
export async function expectResults(page: Page, expected: string[], what: string) {
  await expect.poll(() => foundCount(page), { message: `${what}: «נמצאו N» = ${expected.length}`, ...LOAD }).toBe(expected.length);
  await expect.poll(() => resultIds(page), { message: `${what}: объявления выдачи = каталог в диапазоне`, ...LOAD }).toEqual(expected);
}

export async function openPage(page: Page, path: string) {
  await page.goto(path);
  await foundCount(page);
}

/** Мобайл /search — попап «חיפוש וסינון» (role=dialog); десктоп и /mapview — панель с «טווח מחירים» и «סנן תוצאות». */
export function filterScope(page: Page, mobilePopup: boolean): Locator {
  if (mobilePopup) return page.getByRole('dialog');
  return page
    .locator('div')
    .filter({ visible: true })
    .filter({ has: page.getByText('טווח מחירים', { exact: true }) })
    .filter({ has: page.getByRole('button', { name: 'סנן תוצאות' }) })
    .last();
}

export async function openFilter(page: Page, mobilePopup: boolean): Promise<Locator> {
  await page.getByText(/^סינון מתקדם$/).filter({ visible: true }).first().click();
  const scope = filterScope(page, mobilePopup);
  await expect(scope.getByPlaceholder('מינימום')).toBeVisible(LOAD);
  return scope;
}

export const fields = (scope: Locator) => ({
  min: scope.getByPlaceholder('מינימום'),
  max: scope.getByPlaceholder('מקסימום'),
});
export const thumbs = (scope: Locator) => ({
  min: scope.getByRole('slider', { name: 'Minimum' }),
  max: scope.getByRole('slider', { name: 'Maximum' }),
});
export const rangeLabel = (scope: Locator) => scope.getByText(/^₪[\d,]+ - ₪[\d,]+$/);

/** Ввод значения: 'fill' — вставкой, 'type' — по одной цифре, как пользователь. */
export async function enter(field: Locator, value: number, mode: EnterMode) {
  if (mode === 'fill') {
    await field.fill(String(value));
  } else {
    await field.click();
    await field.press('ControlOrMeta+a');
    await field.press('Backspace');
    await field.pressSequentially(String(value), { delay: 80 });
  }
  await expect(field, 'значение не стёрлось и не поменялось местами при вводе').toHaveValue(String(value));
}

export async function applyFilter(page: Page) {
  await page.getByRole('button', { name: 'סנן תוצאות' }).filter({ visible: true }).first().click();
}

export const thumbValue = async (thumb: Locator) => Number(await thumb.getAttribute('aria-valuenow'));

/** Перетянуть ручку мышью по горизонтали до x (работает и в мобильной эмуляции). */
export async function dragThumb(page: Page, thumb: Locator, toX: number) {
  await thumb.scrollIntoViewIfNeeded();
  const r = (await thumb.boundingBox())!;
  const y = r.y + r.height / 2;
  await page.mouse.move(r.x + r.width / 2, y);
  await page.mouse.down();
  await page.mouse.move(toX, y, { steps: 12 });
  await page.mouse.up();
}

/** Центры ручек: RTL — мин справа, макс слева. */
export async function thumbCenters(scope: Locator) {
  const t = thumbs(scope);
  const a = (await t.min.boundingBox())!;
  const b = (await t.max.boundingBox())!;
  return { minX: a.x + a.width / 2, maxX: b.x + b.width / 2 };
}

/** Порог из середины цен набора (только положительные), чтобы фильтр цены реально сужал выдачу. */
export function pricePoints(catalog: Biz[], ids: string[]) {
  const ps = [...new Set(catalog.filter((b) => ids.includes(b.id)).map(priceOf).filter((p) => p > 0))].sort((a, b) => a - b);
  if (ps.length < 2) throw new Error(`В наборе меньше 2 разных цен (${ps.length}) — данные сайта, не баг`);
  const n = ps.length - 1;
  return { low: ps[Math.floor(n / 4)], mid: ps[Math.floor(n / 2)], high: ps[Math.ceil((3 * n) / 4)] };
}
